MERGE fin.CreditRemedy AS d
USING (VALUES
    ('SUBORDINATE_PARTNERS_CA', 'PRESENTATION', 'ELEVATED', N'إسناد الحسابات الجارية للشركاء', N'Subordinate partners'' current accounts',
     N'يوقّع الشركاء خطاب تبعية لصالح البنوك يمنع سحب أرصدة حساباتهم الجارية الدائنة أو سدادها ما دامت التسهيلات قائمة، وتُعاد تسميتها قروض شركاء مساندة. الجوهر: يتنازل الشركاء قانونيًا عن حق الطلب، فيصبح المبلغ رأس مال مخاطرًا يتحمل الخسارة قبل البنوك.',
     N'Partners sign a subordination letter in favour of the banks that bars withdrawal or repayment of their credit current-account balances while facilities are outstanding; the balances become subordinated shareholder loans. Substance: the partners legally give up the on-demand right, so the money becomes risk capital that absorbs losses before the banks.',
     N'خطاب تبعية موقّع وموثّق لصالح البنوك الدائنة، وقرار الشركاء، وإفصاح في القوائم بأن الرصيد مساند', N'Signed and notarised subordination letter in favour of the lending banks, partners'' resolution, and a note in the statements that the balance is subordinated', 'OWNER_CONSENT', 'SUBORDINATION', 10),
    ('SUBORDINATE_SHAREHOLDER_LOANS', 'PRESENTATION', 'ELEVATED', N'إسناد قروض الشركاء', N'Subordinate shareholder loans',
     N'تُوقَّع اتفاقية تبعية لقروض الشركاء غير المساندة تؤخر سدادها وعوائدها حتى سداد البنوك. الجوهر: تأخر قانوني في الترتيب وفي الاستحقاق، لا مجرد تغيير في المسمى.',
     N'Sign a subordination agreement for the unsubordinated shareholder loans that defers their repayment and any return until the banks are repaid. Substance: a legal change in ranking and maturity, not a change of label.',
     N'اتفاقية تبعية موقّعة لصالح البنوك، وجدول القروض، وإفصاح في القوائم', N'Signed subordination agreement in favour of the banks, the loan schedule, and the note in the statements', 'OWNER_CONSENT', 'SUBORDINATION', 20),
    ('CONVERT_PARTNERS_CA_TO_CAPITAL', 'REAL_ACTION', 'HIGH', N'تحويل الحسابات الجارية إلى رأس مال', N'Convert partners'' current accounts into capital',
     N'يقرر الشركاء زيادة رأس المال برسملة أرصدة حساباتهم الجارية الدائنة، وتُسجل الزيادة في السجل التجاري. أقوى من التبعية: يصبح المبلغ حقوق ملكية دائمة ويعالج خسارة نصف رأس المال.',
     N'Partners resolve a capital increase by capitalising their credit current-account balances and register it with the commercial register. Stronger than subordination: the money becomes permanent equity and cures a half-capital loss.',
     N'قرار الشركاء أو الجمعية غير العادية بزيادة رأس المال، وتعديل عقد التأسيس، وشهادة السجل التجاري المحدثة', N'Partners'' or extraordinary general assembly resolution, amended articles, and the updated commercial registration', 'OWNER_CONSENT', NULL, 30),
    ('CAPITAL_CONTRIBUTION_RESOLUTION', 'PRESENTATION', 'MODERATE', N'توثيق دفعات زيادة رأس المال', N'Document capital contributions as non-refundable',
     N'يصدر الشركاء قرارًا بأن المبالغ المدفوعة لزيادة رأس المال غير قابلة للاسترداد وتُستكمل بها الزيادة. الجوهر: يزول حق الاسترداد، فتُعد حقوق ملكية لا دينًا.',
     N'Partners resolve that the amounts paid towards the capital increase are non-refundable and will complete the increase. Substance: the refund right ends, so they are equity, not debt.',
     N'قرار الشركاء بعدم الاسترداد وبجدول استكمال الزيادة', N'Partners'' resolution of non-refundability with the timetable to complete the increase', 'OWNER_CONSENT', 'CAPITAL_RESOLUTION', 40),
    ('CONVERT_DUE_TO_RELATED_TO_SUB', 'PRESENTATION', 'ELEVATED', N'إسناد المستحق لشركات المجموعة', N'Subordinate amounts due to group companies',
     N'توقّع الشركة الشقيقة الدائنة خطاب تبعية لصالح البنوك وجدولًا لا يبدأ إلا بعد سداد التسهيلات. الجوهر: يتأخر حق الطلب قانونيًا.',
     N'The lending group company signs a subordination letter in favour of the banks with a schedule that starts only after the facilities are repaid. Substance: the demand right is legally deferred.',
     N'خطاب تبعية من الطرف ذي العلاقة، وموافقة مجلسه', N'Subordination letter from the related party and its board approval', 'OWNER_CONSENT', 'SUBORDINATION', 50),
    ('SETTLE_RELATED_RECEIVABLES', 'REAL_ACTION', 'ELEVATED', N'تحصيل المستحق من الأطراف ذات العلاقة', N'Collect amounts due from related parties',
     N'تسدد الشركات الشقيقة أرصدتها نقدًا أو بجدول لا يتجاوز سنة، وتُعتمد سياسة تمنع تمويل الشقيقات. الجوهر: يعود النقد المسرب إلى الشركة.',
     N'Group companies repay their balances in cash or on a schedule of no more than a year, and a policy bars funding them. Substance: the leaked cash comes back.',
     N'كشف حساب بنكي بالتحصيل، واتفاقية جدولة موقعة، وسياسة معتمدة للتعاملات', N'Bank statement of the receipt, a signed repayment schedule, and an approved related-party policy', 'RELATED_PARTIES', NULL, 60),
    ('REPAY_SHAREHOLDER_LOANS', 'REAL_ACTION', 'ELEVATED', N'سداد الشركاء لقروضهم ومسحوباتهم', N'Partners repay their loans and drawings',
     N'يرد الشركاء ما سحبوه من الشركة نقدًا، أو يُقاص بقرار مكتوب مقابل أرباح معلنة مستحقة لهم. الجوهر: نقد يعود أو التزام حقيقي يسقط، لا قيد عكسي.',
     N'Partners pay back what they drew, in cash or by a written set-off against dividends already declared to them. Substance: cash returns or a real liability is extinguished, not a reversing entry.',
     N'إيداع بنكي من الشركاء، أو قرار مقاصة موقع مقابل أرباح معلنة', N'Bank deposit by the partners, or a signed set-off resolution against declared dividends', 'OWNER_CASH', NULL, 70),
    ('OFFSET_PARTNER_BALANCES', 'PRESENTATION', 'MODERATE', N'مقاصة أرصدة الشريك المدينة والدائنة', N'Offset a partner''s debit and credit balances',
     N'حين يكون للشريك نفسه رصيد مدين (مسحوبات) ورصيد دائن (حساب جار)، تُجرى مقاصة باتفاق مكتوب يجيزه عقد الشركة. الجوهر: حق مقاصة قانوني بين الطرفين نفسيهما، فيُعرض الصافي.',
     N'Where the same partner has a debit balance (drawings) and a credit balance (current account), set them off under a written agreement allowed by the articles. Substance: a legal right of set-off between the same parties, so the net is shown.',
     N'اتفاقية مقاصة موقعة من الشريك، وكشف بأرصدة كل شريك', N'Set-off agreement signed by the partner and a statement of each partner''s balances', 'OWNER_CONSENT', NULL, 80),
    ('STOP_PARTNER_DRAWINGS', 'REAL_ACTION', 'ELEVATED', N'إيقاف مسحوبات الشركاء', N'Stop partner drawings',
     N'يقرر الشركاء وقف المسحوبات واستبدالها بتوزيعات تقر بعد القوائم المدققة وفي حدود التدفق الحر. الجوهر: يبقى النقد في الشركة.',
     N'Partners resolve to stop drawings and replace them with dividends approved after the audited statements and within free cash flow. Substance: the cash stays in the company.',
     N'قرار الشركاء بسياسة التوزيع', N'Partners'' resolution on the distribution policy', 'POLICY', NULL, 90),
    ('RELEASE_RELATED_GUARANTEES', 'REAL_ACTION', 'ELEVATED', N'رفع الكفالات المقدمة للشقيقات', N'Release guarantees given for group companies',
     N'تطلب الشركة من بنوك الشقيقات إحلال كفالة الشركاء أو ضمانات الشقيقة نفسها محل كفالتها. الجوهر: يزول الالتزام المحتمل قانونيًا.',
     N'The company asks the group companies'' banks to replace its guarantee with the partners'' guarantee or the group company''s own security. Substance: the contingent obligation is legally released.',
     N'خطاب البنك برفع الكفالة', N'The bank''s letter releasing the guarantee', 'RELATED_PARTIES', NULL, 100),
    ('TERM_OUT_ST_FUNDING', 'REAL_ACTION', 'HIGH', N'تحويل تمويل الأصول الطويلة إلى قرض طويل الأجل', N'Term out short-term funding of long-term assets',
     N'يُعاد تمويل الجزء من القروض قصيرة الأجل الذي مول أصولًا ثابتة أو مشاريع بقرض لأجل يتوافق مع عمر الأصل (خمس إلى سبع سنوات بفترة سماح)، ويمكن طلب دعم برامج التمويل الصناعي. الجوهر: التزام سداد جديد طويل الأجل بعقد موقع.',
     N'Refinance the part of short-term loans that funded fixed assets or projects with a term loan matched to the asset life (five to seven years with a grace period); industrial funding programmes may support it. Substance: a new signed long-term repayment obligation.',
     N'عقد القرض لأجل الموقع وإشعار السداد للخطوط القصيرة', N'The signed term-loan agreement and the repayment notice of the short-term lines', 'LENDERS', NULL, 110),
    ('REFINANCE_MATURITY_WALL', 'REAL_ACTION', 'HIGH', N'إعادة تمويل الاستحقاقات المتركزة', N'Refinance the maturity wall',
     N'تُعاد جدولة أقساط السنة القادمة أو تمويلها بقرض جديد قبل نهاية الفترة. لا يُنقل الجزء المتداول إلى طويل الأجل إلا باتفاق موقع قبل تاريخ القائمة (معيار المحاسبة الدولي 1 الفقرة 72).',
     N'Reschedule next year''s instalments or refinance them with a new loan before the period end. The current portion moves to long term only with an agreement signed before the statement date (IAS 1.72).',
     N'اتفاقية إعادة التمويل أو الجدولة موقعة ومؤرخة قبل نهاية الفترة', N'Refinancing or rescheduling agreement signed and dated before the period end', 'LENDERS', NULL, 120),
    ('COMMITTED_FACILITY', 'REAL_ACTION', 'ELEVATED', N'تسهيل ملتزم متجدد لأكثر من سنة', N'Obtain a committed revolving facility',
     N'يُحوَّل جزء من الخطوط غير الملتزمة إلى تسهيل متجدد ملتزم لأجل ثلاث سنوات مقابل رسم التزام. الجوهر: يلتزم البنك قانونيًا بالإتاحة، فيُحسب غير المسحوب مصدرًا للسيولة.',
     N'Convert part of the uncommitted lines into a three-year committed revolving facility for a commitment fee. Substance: the bank is legally bound to lend, so the undrawn part counts as a liquidity source.',
     N'اتفاقية التسهيل الملتزم ومدة الالتزام', N'The committed facility agreement and its commitment period', 'LENDERS', NULL, 130),
    ('EXTEND_FACILITY_TENORS', 'REAL_ACTION', 'HIGH', N'تجديد التسهيلات قبل انتهائها وإطالة آجالها', N'Renew facilities early and extend tenors',
     N'تُجدد الحدود قبل انتهائها بثلاثة أشهر على الأقل، ويُطلب أجل يتجاوز سنة لجزء منها. الجوهر: موافقة ائتمانية جديدة مسجلة.',
     N'Renew limits at least three months before expiry and ask for a tenor beyond one year for part of them. Substance: a new recorded credit approval.',
     N'خطاب الموافقة الائتمانية المجددة', N'The renewed credit approval letter', 'LENDERS', NULL, 140),
    ('DIVERSIFY_LENDERS', 'REAL_ACTION', 'HIGH', N'توزيع التسهيلات على أكثر من بنك', N'Diversify lenders',
     N'تُفتح علاقة ثانية وثالثة وتُنقل إليها حصة من الحدود حتى لا يتجاوز أكبر بنك نصف الإجمالي. الجوهر: مصادر تمويل مستقلة.',
     N'Open a second and third banking relationship and move part of the limits so that the largest bank holds no more than half. Substance: independent funding sources.',
     N'خطابات موافقة البنوك الجديدة', N'Approval letters of the new banks', 'LENDERS', NULL, 150),
    ('WAIVER_BEFORE_PERIOD_END', 'PRESENTATION', 'HIGH', N'الحصول على التنازل عن الخرق قبل نهاية الفترة', N'Obtain the covenant waiver before the period end',
     N'يُطلب التنازل أو تعديل التعهد قبل تاريخ القائمة، فيبقى القرض طويل الأجل في تصنيفه. التنازل بعد نهاية الفترة لا يعيد التصنيف (معيار المحاسبة الدولي 1 الفقرة 74)، لكنه يزيل تنزيل الخرق القائم.',
     N'Request the waiver or covenant reset before the statement date so that the term loan keeps its classification. A waiver after the period end does not restore it (IAS 1.74) but removes the open-breach notch.',
     N'خطاب التنازل من البنك مؤرخًا قبل نهاية الفترة، أو بعدها لإزالة التنزيل فقط', N'The bank''s waiver letter dated before the period end, or after it to remove the notch only', 'LENDERS', 'WAIVER_BEFORE_PERIOD_END', 160),
    ('COLLECT_OVERDUE_AR', 'REAL_ACTION', 'ELEVATED', N'حملة تحصيل للذمم المتأخرة', N'Collection drive on overdue receivables',
     N'تُطالب الشركة المدينين المتأخرين فوق 180 يومًا بجدول سداد موقع مع سندات لأمر، وتوقف البيع الآجل لمن تجاوز الحد، ويُستخدم القضاء التنفيذي للسندات. للحكومي: متابعة المستخلصات في منصة اعتماد. الجوهر: نقد محصل.',
     N'Ask debtors over 180 days for a signed repayment schedule backed by promissory notes, stop credit sales to those over limit, and enforce notes through the Enforcement Court; for government, follow up the certificates on the Etimad platform. Substance: collected cash.',
     N'كشف أعمار الذمم قبل وبعد، وكشوف التحصيل البنكية', N'Aging report before and after, and bank collection statements', 'OPERATIONS', NULL, 170),
    ('PROVIDE_AND_ENFORCE_OLD_AR', 'REAL_ACTION', 'HIGH', N'تكوين مخصص للذمم فوق سنة ومتابعتها قضائيًا', N'Provide for receivables over a year and enforce them',
     N'يُكوَّن مخصص كامل لغير الحكومي منها، وتُرفع دعاوى التنفيذ. لا يحسن المخصص صافي الثروة المعدلة لأنه يُخصم أصلًا، لكنه يجعل القوائم صادقة ويرفع ثقة البنك. الجوهر: اعتراف بالخسارة، لا تجميل.',
     N'Book a full allowance for the non-government part and file enforcement claims. The allowance does not improve adjusted net worth, which already deducts it, but it makes the statements true and raises bank trust. Substance: a loss recognised, not dressed up.',
     N'محضر اعتماد المخصص وصحف الدعاوى', N'Allowance approval minute and the filed claims', 'OPERATIONS', NULL, 180),
    ('FACTOR_WITHOUT_RECOURSE', 'REAL_ACTION', 'ELEVATED', N'بيع الذمم دون حق رجوع', N'Factor receivables without recourse',
     N'تُباع ذمم جيدة لجهة تمويل مرخصة من البنك المركزي دون حق رجوع، ويُسدد بالحصيلة جزء من القروض القصيرة. الجوهر: تنتقل مخاطر الائتمان فعلًا إلى المشتري؛ البيع مع حق الرجوع يبقى دينًا (ADJ-FACTORING).',
     N'Sell good receivables to a SAMA-licensed finance company without recourse and use the proceeds to repay short-term loans. Substance: the credit risk really passes to the buyer; factoring with recourse stays debt (ADJ-FACTORING).',
     N'عقد البيع دون حق رجوع ورأي المراجع بإلغاء الاعتراف', N'The non-recourse sale agreement and the auditor''s derecognition view', 'LENDERS', NULL, 190),
    ('CREDIT_INSURANCE', 'REAL_ACTION', 'ELEVATED', N'تأمين ائتمان الذمم', N'Insure trade receivables',
     N'تُؤمَّن الذمم الخاصة لدى شركة تأمين مرخصة، ويُحال حق التعويض للبنك. الجوهر: انتقال جزء من خسارة التعثر إلى المؤمن، ويُعامل التعويض المحال ضمانًا بخصم 30%.',
     N'Insure private receivables with a licensed insurer and assign the indemnity to the bank. Substance: part of the default loss passes to the insurer; the assigned indemnity counts as collateral at a 30% haircut.',
     N'وثيقة التأمين وإحالة الحق للبنك', N'The policy and its assignment to the bank', 'OPERATIONS', NULL, 200),
    ('RELEASE_RETENTIONS', 'REAL_ACTION', 'ELEVATED', N'استرداد المحتجزات المتأخرة', N'Recover overdue retentions',
     N'تُستكمل شهادات الاستلام الابتدائي والنهائي وتُستبدل المحتجزات بخطاب ضمان محتجزات حيث يسمح العقد. الجوهر: نقد يعود مقابل التزام محتمل أصغر.',
     N'Complete the provisional and final acceptance certificates and replace retentions with a retention bond where the contract allows. Substance: cash comes back against a smaller contingent obligation.',
     N'شهادات الاستلام وخطاب ضمان المحتجزات', N'Acceptance certificates and the retention bond', 'OPERATIONS', NULL, 210),
    ('LIQUIDATE_SLOW_STOCK', 'REAL_ACTION', 'ELEVATED', N'تصفية المخزون الراكد', N'Clear slow-moving stock',
     N'يُباع الراكد بخصم أو يُعاد للمورد أو يُشطب، ويُسدد بالحصيلة تمويل الاستيراد. يفترض النموذج البيع بنصف القيمة الدفترية والباقي خسارة. الجوهر: نقد محصل وخسارة معترف بها.',
     N'Sell slow stock at a discount, return it to the supplier, or write it off, and repay import finance with the proceeds. The pro-forma assumes a sale at half the book value and the rest as a loss. Substance: cash collected and a loss recognised.',
     N'فواتير البيع ومحضر الإتلاف أو الإرجاع', N'Sales invoices and the disposal or return record', 'OPERATIONS', NULL, 220),
    ('PAY_OVERDUE_SUPPLIERS', 'REAL_ACTION', 'HIGH', N'سداد المتأخرات للموردين بتمويل رأس مال عامل', N'Clear supplier arrears with working-capital funding',
     N'تُسدد المتأخرات من قرض رأس مال عامل لأجل سنتين أو من حصيلة التحصيل، ويُتفاوض على آجال مكتوبة جديدة. الجوهر: التزام متأخر يُستبدل بدين منظم بجدول.',
     N'Pay the arrears with a two-year working-capital loan or collection proceeds, and agree new written terms. Substance: an overdue obligation is replaced by scheduled debt.',
     N'كشوف السداد للموردين وعقد القرض', N'Supplier payment statements and the loan agreement', 'LENDERS', NULL, 230),
    ('SUPPLIER_FINANCE_TRANSPARENCY', 'PRESENTATION', 'ELEVATED', N'إفصاح تمويل الموردين وضبطه', N'Disclose and cap supplier finance',
     N'يُفصح عن برنامج تمويل الموردين كما تطلب تعديلات معيار المحاسبة الدولي 7 والمعيار الدولي 7 (2024)، ويُحد بسقف. لا يحسن الدرجة لأنه دين أصلًا؛ إخفاؤه يعد معلومة مضللة.',
     N'Disclose the supplier-finance programme as the 2024 amendments to IAS 7 and IFRS 7 require, and cap it. It does not improve the grade because it is debt already; hiding it would mislead.',
     N'إيضاح البرنامج في القوائم وعقده', N'The note in the statements and the programme agreement', 'DISCLOSURE', NULL, 240),
    ('CAPITAL_INJECTION', 'REAL_ACTION', 'HIGH', N'زيادة رأس المال نقدًا', N'Cash capital injection',
     N'يضخ الشركاء نقدًا لزيادة رأس المال ويُسدد به جزء من القروض القصيرة. الجوهر: مال جديد مخاطر.',
     N'Partners inject cash to increase capital, and part of the short-term loans is repaid with it. Substance: new risk capital.',
     N'قرار زيادة رأس المال وإيداع بنكي في حساب الشركة', N'Capital increase resolution and the bank deposit in the company''s account', 'OWNER_CASH', 'CAPITAL_RESOLUTION', 250),
    ('RECAPITALISE', 'REAL_ACTION', 'CRITICAL', N'معالجة خسارة نصف رأس المال', N'Recapitalise after losing half the capital',
     N'وفق نظام الشركات: تدعو الإدارة الشركاء خلال المدة النظامية لتقرير الاستمرار مع زيادة رأس المال نقدًا أو برسملة قروضهم، أو تخفيض رأس المال لإطفاء الخسائر مع زيادة جديدة. التخفيض وحده لا يغير صافي الثروة، فلا يُعد معالجة دون مال جديد.',
     N'Under the Companies Law management calls the partners within the statutory period to resolve continuation with a cash capital increase or capitalisation of their loans, or a capital reduction to absorb losses together with fresh capital. A reduction alone does not change net worth and is not a remedy without new money.',
     N'قرار الجمعية أو الشركاء والإيداع البنكي وتحديث السجل التجاري', N'The assembly or partners'' resolution, the bank deposit and the updated commercial registration', 'OWNER_CASH', 'CAPITAL_RESOLUTION', 260),
    ('RETAIN_EARNINGS', 'REAL_ACTION', 'ELEVATED', N'احتجاز الأرباح وتعليق التوزيعات', N'Retain earnings and suspend dividends',
     N'تُعلق التوزيعات حتى يعود الرفع دون حد معلن (مثل الدين ثلاثة أمثال EBITDA)، وتُحتجز الأرباح. الجوهر: نقد لا يخرج.',
     N'Suspend dividends until leverage is back under a stated limit (for example debt at three times EBITDA) and retain profit. Substance: cash that does not leave.',
     N'قرار الشركاء بتعليق التوزيع', N'Partners'' resolution suspending distributions', 'POLICY', NULL, 270),
    ('CONVERT_DIVIDENDS_PAYABLE', 'REAL_ACTION', 'HIGH', N'رسملة الأرباح المعلنة غير المدفوعة', N'Capitalise declared but unpaid dividends',
     N'يقرر الشركاء رسملة الأرباح المعلنة في زيادة رأس المال بدل صرفها. الجوهر: يسقط الالتزام النقدي ويحل محله رأس مال.',
     N'Partners resolve to capitalise the declared dividends in a capital increase instead of paying them. Substance: the cash obligation ends and is replaced by capital.',
     N'قرار الشركاء وتعديل عقد الشركة', N'Partners'' resolution and the amended articles', 'OWNER_CONSENT', NULL, 280),
    ('APPLY_MARGINS_TO_DEBT', 'REAL_ACTION', 'ELEVATED', N'استخدام الهوامش في سداد الالتزامات التي تغطيها', N'Apply cash margins to the obligations they secure',
     N'تُطلب من البنك تسوية القبولات المستحقة من الهوامش المحجوزة مقابلها، والإفراج عن هوامش الاعتمادات والضمانات المنتهية. الجوهر: سداد فعلي أو إفراج فعلي.',
     N'Ask the bank to settle due acceptances from the margins held against them and to release margins of expired LCs and guarantees. Substance: actual repayment or actual release.',
     N'إشعار البنك بالتسوية أو الإفراج', N'The bank''s settlement or release notice', 'LENDERS', NULL, 290),
    ('REPLACE_MARGINS_WITH_LIMITS', 'REAL_ACTION', 'HIGH', N'استبدال الهوامش النقدية بحدود ضمانات', N'Replace cash margins with guarantee limits',
     N'يُتفاوض على خفض نسبة الهامش النقدي على خطابات الضمان مقابل حد ضمانات أو رهن أصل آخر. الجوهر: يتحرر النقد بموافقة البنك.',
     N'Negotiate a lower cash-margin ratio on guarantees against a guarantee limit or a pledge of another asset. Substance: cash is freed with the bank''s approval.',
     N'موافقة البنك على نسبة الهامش الجديدة', N'The bank''s approval of the new margin ratio', 'LENDERS', NULL, 300),
    ('SELL_NON_OPERATING_ASSETS', 'REAL_ACTION', 'HIGH', N'بيع الأصول غير التشغيلية وسداد الدين', N'Sell non-operating assets and repay debt',
     N'تُباع العقارات الاستثمارية أو الاستثمارات غير الاستراتيجية ويُسدد الدين. يفترض النموذج البيع بالقيمة الدفترية. الجوهر: نقد من بيع حقيقي.',
     N'Sell investment property or non-core investments and repay debt. The pro-forma assumes a sale at book value. Substance: cash from a real sale.',
     N'عقد البيع وإفراغ الصك وإشعار السداد', N'Sale contract, title transfer and repayment notice', 'ASSET_SALE', NULL, 310),
    ('PERFECT_COLLATERAL', 'PRESENTATION', 'ELEVATED', N'استكمال توثيق الضمانات', N'Perfect the collateral',
     N'تُسجل الرهون العقارية في السجل العقاري وتُحدث التقييمات (أقل من 24 شهرًا من مقيم معتمد من تقييم) ويُربط الضمان بالتسهيل في المنصة. الجوهر: حق امتياز قابل للتنفيذ. يحسن درجة التسهيل فقط.',
     N'Register mortgages in the Real Estate Registry, refresh valuations (under 24 months, by a TAQEEM-accredited valuer) and link the collateral to the facility on the platform. Substance: an enforceable security interest. It improves the facility grade only.',
     N'صك الرهن المسجل وتقرير التقييم', N'The registered mortgage deed and the valuation report', 'LENDERS', NULL, 320),
    ('DOCUMENT_GUARANTORS', 'PRESENTATION', 'ELEVATED', N'توثيق ملاءة الكفلاء', N'Document the guarantors'' net worth',
     N'يقدم الكفلاء بيان ثروة موقعًا مع كشوف بنكية وصكوك وقائمة بكفالاتهم الأخرى، يُحدث سنويًا. الجوهر: ملاءة قابلة للتحقق. يحسن درجة التسهيل فقط.',
     N'Guarantors provide a signed net-worth statement with bank statements, title deeds and a list of their other guarantees, refreshed yearly. Substance: verifiable solvency. It improves the facility grade only.',
     N'بيان الثروة الموقع والمستندات المؤيدة', N'The signed net-worth statement and supporting documents', 'OWNER_CONSENT', NULL, 330),
    ('DISCLOSE_BREAKDOWNS', 'PRESENTATION', 'MODERATE', N'إدخال الإفصاحات الناقصة', N'Enter the missing disclosures',
     N'تُدخل أعمار الذمم والمخصص، وتفصيل المخزون الراكد، وجدول استحقاق الدين، والنقد المقيد، والالتزامات المحتملة، وتكاليف الموظفين، من إيضاحات القوائم المدققة. الجوهر: معلومات موجودة أصلًا في الإيضاحات؛ لا تُدخل أرقام بلا مصدر.',
     N'Enter receivables aging and allowance, slow stock, the debt maturity table, restricted cash, contingents and staff costs from the audited notes. Substance: information already in the notes; no figure is entered without a source.',
     N'إيضاحات القوائم المدققة أو تقرير المراجع عن الأعمار', N'The audited notes or the auditor''s aging report', 'DISCLOSURE', NULL, 340),
    ('REDUCE_CONCENTRATION', 'REAL_ACTION', 'HIGH', N'تنويع العملاء والموردين', N'Diversify customers and suppliers',
     N'خطة مبيعات مكتوبة لخفض أكبر عميل دون 25% خلال سنتين، وعقد طويل مع العميل الرئيسي بشروط إنهاء واضحة، ومورد بديل مؤهل. الجوهر: تغيير في الأعمال يظهر في السنوات القادمة.',
     N'A written sales plan to bring the largest customer under 25% within two years, a long contract with the main customer with clear termination terms, and a qualified second supplier. Substance: a business change that shows in coming years.',
     N'العقود الموقعة وخطة المبيعات', N'Signed contracts and the sales plan', 'OPERATIONS', NULL, 350),
    ('FX_HEDGE', 'REAL_ACTION', 'ELEVATED', N'تحوط مخاطر الصرف', N'Hedge the FX exposure',
     N'تُغطى المشتريات والدين بعملات غير الدولار بعقود آجلة أو بتمويل بنفس العملة. الجوهر: مركز مقفل بعقد.',
     N'Cover purchases and debt in non-USD currencies with forwards or with funding in the same currency. Substance: a position closed by contract.',
     N'تأكيدات العقود الآجلة', N'Forward contract confirmations', 'LENDERS', NULL, 360),
    ('RATE_HEDGE', 'REAL_ACTION', 'ELEVATED', N'تثبيت العائد على جزء من الدين', N'Fix the rate on part of the debt',
     N'تُبرم مقايضة ربح (عائد ثابت مقابل متغير) متوافقة مع الشريعة على نصف الدين طويل الأجل على الأقل. الجوهر: تكلفة محددة بعقد.',
     N'Enter a Sharia-compliant profit-rate swap (fixed for floating) on at least half of the term debt. Substance: a cost fixed by contract.',
     N'تأكيد المقايضة', N'The swap confirmation', 'LENDERS', NULL, 370),
    ('COST_RESTRUCTURING', 'REAL_ACTION', 'HIGH', N'خفض التكاليف الثابتة', N'Cut fixed costs',
     N'يُراجع هيكل التكاليف: دمج مواقع، وتحويل جزء من الرواتب إلى حوافز مرتبطة بالمبيعات، وإعادة التفاوض على الإيجارات. الأثر يظهر في القائمة التالية، فلا تحويل افتراضي هنا.',
     N'Review the cost base: merge sites, turn part of salaries into sales-linked incentives, renegotiate rents. The effect shows in the next statement, so there is no pro-forma here.',
     N'خطة التكاليف المعتمدة', N'The approved cost plan', 'OPERATIONS', NULL, 380),
    ('IMPROVE_FUNDING_COST', 'REAL_ACTION', 'HIGH', N'خفض تكلفة التمويل', N'Lower the funding cost',
     N'تُطلب عروض من عدة بنوك، وتُقدم ضمانات أو تبعية مقابل خفض الهامش، وتُسدد الخطوط الأغلى أولًا. الجوهر: عقود تسعير جديدة.',
     N'Ask several banks for offers, give security or subordination against a lower margin, and repay the dearest lines first. Substance: new pricing agreements.',
     N'عروض التسعير الموقعة', N'Signed pricing offers', 'LENDERS', NULL, 390)
) AS s (Code, Kind, MinLevel, NameAr, NameEn, TextAr, TextEn, EvidenceAr, EvidenceEn, Funding, SetsEvidence, SortOrder)
   ON d.Code = s.Code
WHEN NOT MATCHED THEN
    INSERT (Code, Kind, MinLevel, NameAr, NameEn, TextAr, TextEn, EvidenceAr, EvidenceEn, Funding, SetsEvidence, SortOrder)
    VALUES (s.Code, s.Kind, s.MinLevel, s.NameAr, s.NameEn, s.TextAr, s.TextEn, s.EvidenceAr, s.EvidenceEn, s.Funding, s.SetsEvidence, s.SortOrder);
GO
MERGE fin.CreditRemedyTrigger AS d
USING (SELECT r.CreditRemedyId AS RemedyId, v.TriggerCode, v.SortOrder
       FROM (VALUES
    ('SUBORDINATE_PARTNERS_CA', 'DEBT_TO_CAPITAL', 1),
    ('SUBORDINATE_PARTNERS_CA', 'LIQUIDITY_COVERAGE', 2),
    ('SUBORDINATE_PARTNERS_CA', 'TL_TO_TNW', 3),
    ('SUBORDINATE_PARTNERS_CA', 'LIQUIDITY_SGL4', 4),
    ('SUBORDINATE_SHAREHOLDER_LOANS', 'DEBT_TO_CAPITAL', 1),
    ('SUBORDINATE_SHAREHOLDER_LOANS', 'TL_TO_TNW', 2),
    ('SUBORDINATE_SHAREHOLDER_LOANS', 'DEBT_TO_EBITDA', 3),
    ('CONVERT_PARTNERS_CA_TO_CAPITAL', 'DEBT_TO_CAPITAL', 1),
    ('CONVERT_PARTNERS_CA_TO_CAPITAL', 'EQUITY_RATIO', 2),
    ('CONVERT_PARTNERS_CA_TO_CAPITAL', 'ACC_LOSS_TO_CAPITAL', 3),
    ('CONVERT_PARTNERS_CA_TO_CAPITAL', 'HALF_CAPITAL_LOST', 4),
    ('CAPITAL_CONTRIBUTION_RESOLUTION', 'DEBT_TO_CAPITAL', 1),
    ('CAPITAL_CONTRIBUTION_RESOLUTION', 'TL_TO_TNW', 2),
    ('CONVERT_DUE_TO_RELATED_TO_SUB', 'DUE_TO_RELATED_TO_TNW', 1),
    ('CONVERT_DUE_TO_RELATED_TO_SUB', 'LIQUIDITY_COVERAGE', 2),
    ('SETTLE_RELATED_RECEIVABLES', 'RELATED_TO_TNW', 1),
    ('SETTLE_RELATED_RECEIVABLES', 'RELATED_PARTY_EXPOSURE', 2),
    ('SETTLE_RELATED_RECEIVABLES', 'NON_OPERATING_ASSETS_SHARE', 3),
    ('REPAY_SHAREHOLDER_LOANS', 'DUE_FROM_SHAREHOLDERS_TO_TNW', 1),
    ('REPAY_SHAREHOLDER_LOANS', 'RELATED_PARTY_DRAIN', 2),
    ('REPAY_SHAREHOLDER_LOANS', 'RELATED_PARTY_EXPOSURE', 3),
    ('OFFSET_PARTNER_BALANCES', 'DUE_FROM_SHAREHOLDERS_TO_TNW', 1),
    ('OFFSET_PARTNER_BALANCES', 'DEBT_TO_CAPITAL', 2),
    ('STOP_PARTNER_DRAWINGS', 'PARTNER_DRAWINGS_TO_CFO', 1),
    ('STOP_PARTNER_DRAWINGS', 'RELATED_PARTY_DRAIN', 2),
    ('STOP_PARTNER_DRAWINGS', 'FUNDING_GAP', 3),
