MERGE fin.StrengtheningPlan AS d
USING (VALUES
    ('OWNER_SUPPORT_NO_CASH', 'PACKAGE', N'دعم الشركاء دون نقد جديد', N'Partner support without new cash',
     N'إعادة تصنيف أموال الشركاء إلى رأس مال مخاطر: إسناد الحسابات الجارية والقروض، والرسملة، وتوثيق دفعات زيادة رأس المال، ومقاصة الأرصدة. لا تحتاج نقدًا بل توقيعات وقرارات.',
     N'Turns the partners'' money into risk capital: subordinating current accounts and loans, capitalising, documenting capital contributions and offsetting balances. It needs signatures and resolutions, not cash.', NULL, 10),
    ('CAPITAL_STRENGTHENING', 'PACKAGE', N'تقوية رأس المال', N'Capital strengthening',
     N'نقد جديد من الشركاء مع احتجاز الأرباح وإيقاف المسحوبات: يعالج خسارة رأس المال ويخفض الرفع ويقوي السيولة.',
     N'New cash from the partners with retained earnings and no drawings: cures the capital loss, lowers leverage and strengthens liquidity.', NULL, 20),
    ('LIQUIDITY_AND_TENOR', 'PACKAGE', N'السيولة وآجال التمويل', N'Liquidity and debt tenor',
     N'مواءمة آجال التمويل مع الأصول: التنازل عن الخرق قبل نهاية الفترة، وتحويل التمويل القصير للأصول الطويلة إلى قرض طويل، وإعادة تمويل الاستحقاقات المتركزة، وحدود ملتزمة.',
     N'Matches the tenor of funding with the assets: the waiver before the period end, short funding of long assets termed out, the maturity wall refinanced, committed lines.', NULL, 30),
    ('WORKING_CAPITAL_RELEASE', 'PACKAGE', N'تحرير رأس المال العامل', N'Working capital release',
     N'تحويل الذمم المتأخرة والمحتجزات والمخزون الراكد إلى نقد، وسداد متأخرات الموردين بتمويل منظم.',
     N'Turns overdue receivables, retentions and slow stock into cash, and pays overdue suppliers with structured funding.', NULL, 40),
    ('DELEVERAGING', 'PACKAGE', N'خفض المديونية', N'Deleveraging',
     N'بيع الأصول غير التشغيلية واستخدام الهوامش وتحصيل المستحق من الأطراف ذات العلاقة في سداد الدين.',
     N'Sells non-operating assets and uses margins and amounts collected from related parties to repay debt.', NULL, 50),
    ('RELATED_PARTY_CLEANUP', 'PACKAGE', N'تنظيف تعاملات الأطراف ذات العلاقة', N'Related-party clean-up',
     N'إغلاق تسرب النقد إلى الشركاء والشقيقات: التحصيل والمقاصة وإيقاف المسحوبات ورفع الكفالات.',
     N'Stops cash leaking to the partners and sister companies: collection, offset, no drawings, guarantees released.', NULL, 60),
    ('ASSET_QUALITY_CLEANUP', 'PACKAGE', N'تنظيف جودة الأصول', N'Asset quality clean-up',
     N'الاعتراف بالخسائر الكامنة في الذمم القديمة والمخزون الراكد. قد يخفض حقوق الملكية في الحساب التقديري، لكنه يجعل الميزانية صادقة ويزيل الخصم الذي يطبقه المحلل على كل حال.',
     N'Recognises the losses hidden in old receivables and slow stock. It may lower equity in the pro-forma, but it makes the balance sheet true and removes the haircut the analyst applies anyway.', NULL, 70),
    ('RISK_HEDGING', 'PACKAGE', N'التحوط من مخاطر السوق', N'Market risk hedging',
     N'تحوط مخاطر الصرف وتثبيت العائد على جزء من الدين.',
     N'Hedges the currency exposure and fixes the rate on part of the debt.', NULL, 80),
    ('OPTIMAL_NO_NEW_CASH', 'OPTIMAL', N'الخطة المثلى دون نقد جديد من الشركاء', N'The best plan without new cash from the partners',
     N'يختار النظام في كل خطوة الحل الذي يعطي أكبر تحسن في الدرجة (ثم في المجموع المرجح) من الحلول التي لا تحتاج نقدًا جديدًا من الشركاء، ويتوقف حين لا يحسّن حلٌّ الدرجةَ أو المجموع بخمسة أجزاء من مئة نقطة على الأقل، أو بعد ثماني خطوات.',
     N'At every step the system picks the remedy that improves the grade most (then the weighted score) among those that need no new cash from the partners, and stops when no remedy improves the grade or the score by at least five hundredths of a point, or after eight steps.', 'OWNER_CASH', 90),
    ('OPTIMAL', 'OPTIMAL', N'الخطة المثلى', N'The best plan',
     N'مثل السابقة من كل الحلول بما فيها النقد الجديد من الشركاء.',
     N'As the previous one, from all remedies including new cash from the partners.', NULL, 100)
) AS s (Code, Kind, NameAr, NameEn, TextAr, TextEn, ExcludeFunding, SortOrder)
   ON d.Code = s.Code
WHEN NOT MATCHED THEN
    INSERT (Code, Kind, NameAr, NameEn, TextAr, TextEn, ExcludeFunding, SortOrder)
    VALUES (s.Code, s.Kind, s.NameAr, s.NameEn, s.TextAr, s.TextEn, s.ExcludeFunding, s.SortOrder);
GO
