MERGE fin.CreditText AS d
USING (VALUES
    ('RECLASS', 'ADJ_IMPAIRMENTS', N'إضافة الهبوط في القيمة إلى EBITDA', N'Impairments added back to EBITDA',
     N'الهبوط في قيمة الأصول بند غير نقدي، فيُعاد إلى EBITDA حتى لا يُحسب مرتين مع ضعف الأصل في الميزانية.',
     N'Impairment is non-cash, so it is added back to EBITDA and not counted twice with the weaker asset on the balance sheet.'),
    ('RECLASS', 'ADJ_CAP_INTEREST', N'الفائدة المرسملة تُعد تكلفة تمويل', N'Capitalised interest treated as interest',
     N'الفائدة التي رُسملت على الأصول تحت الإنشاء تُضاف إلى تكلفة التمويل: هي نقد يُدفع للبنك أيًا كانت معالجتها المحاسبية.',
     N'Interest capitalised on assets under construction is added to interest: it is cash paid to the bank whatever its accounting.'),
    ('RECLASS', 'ADJ_RESTRICTED_CASH', N'النقد المقيد ليس نقدًا متاحًا', N'Restricted cash is not available cash',
     N'الهوامش والودائع المرهونة لا تُستخدم في السداد، فتُطرح من النقد في حساب صافي الدين والسيولة.',
     N'Margins and pledged deposits cannot pay debt, so they are taken out of cash for net debt and liquidity.'),
    ('RECLASS', 'ADJ_SHL_SUB', N'قروض الشركاء المساندة', N'Subordinated shareholder loans',
     N'تُعد حقوق ملكية حين يثبت خطاب التبعية الموقّع أنها لا تُسدد قبل البنوك، وتبقى دينًا بدونه.',
     N'Equity when a signed subordination letter shows they are not repaid before the banks; debt without it.'),
    ('RECLASS', 'ADJ_CAPITAL_CONTRIB', N'دفعات زيادة رأس المال', N'Capital contributions',
     N'تُعد حقوق ملكية حين يثبت قرار الشركاء أنها لزيادة رأس المال، وتبقى التزامًا قابلًا للسحب بدونه.',
     N'Equity when the partners'' resolution shows they are for a capital increase; a withdrawable liability without it.'),
    ('RECLASS', 'ADJ_LEASE', N'التزامات الإيجار دين', N'Lease liabilities are debt',
