-- GENERAL_CORPORATE version 2: General corporates: industry and services
IF NOT EXISTS (SELECT 1 FROM fin.Scorecard WHERE Code = 'GENERAL_CORPORATE' AND VersionNo = 2)
    INSERT fin.Scorecard (Code, VersionNo, NameAr, NameEn, SectorNoteAr, CurrencyId, AmountUnit, MinCoveragePct, QualitativeBoundNotches,
                          SupportMaxAgeMonths, Status, DisclaimerAr, DisclaimerEn)
    SELECT 'GENERAL_CORPORATE', 2, N'الشركات العامة: الصناعة والخدمات', N'General corporates: industry and services',
           N'الشركات الصناعية والخدمية وما لا يندرج في القطاعين الآخرين؛ البطاقة الافتراضية',
           cu.CurrencyId, 1000000, 70, 3, 12, 'DRAFT',
           N'تقييم داخلي يعتمد سلّم موديز (Moody''s) للتصنيف طويل الأجل وطريقة بطاقات التقييم المنشورة: درجة لكل مقياس على خط مستمر ووزن لكل عامل؛ والحدود معايرة بخبرة المحلل للسوق السعودية. ليس تصنيفًا صادرًا عن موديز ولا عن أي وكالة، ولا يحل محل التصنيف الداخلي للبنك.',
           N'An internal assessment on Moody''s long-term rating scale and its published scorecard approach (a score per metric on a linear continuum, a weight per factor); the thresholds are calibrated by expert judgment for the Saudi market. It is not a rating issued by Moody''s or any agency, and it does not replace a bank''s internal rating.'
    FROM ref.Currency AS cu WHERE cu.Code = 'SAR';
MERGE fin.ScorecardMetric AS d
USING (SELECT sc.ScorecardId, m.CreditMetricId, v.FactorCode, v.Weight, v.B0, v.B1, v.B2, v.B3, v.B4, v.B5, v.B6, v.B7, v.B8, v.SortOrder
       FROM (VALUES
    ('REVENUE_SIZE', 'SCALE', 15, 150000, 75000, 30000, 10000, 3000, 750, 100, 20, 2, 1),
    ('BUSINESS_PROFILE', 'BUSINESS_PROFILE', 12, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2),
    ('REV_TOP5_SHARE', 'BUSINESS_PROFILE', 3, 0, 5, 15, 30, 45, 60, 75, 90, 100, 3),
    ('EBITDA_MARGIN', 'PROFITABILITY_EFFICIENCY', 6, 45, 32, 25, 18, 12, 7, 3, 0, -10, 4),
    ('ROA', 'PROFITABILITY_EFFICIENCY', 2, 30, 22, 15, 9, 5, 2, 0, -3, -10, 5),
    ('BREAKEVEN_SAFETY_MARGIN', 'PROFITABILITY_EFFICIENCY', 2, 80, 60, 45, 30, 20, 12, 5, 0, -20, 6),
    ('DEBT_TO_EBITDA', 'LEVERAGE_COVERAGE', 8, 0, 0.5, 1.5, 2.5, 3.5, 4.5, 6, 8, 12, 7),
    ('RCF_TO_NET_DEBT', 'LEVERAGE_COVERAGE', 4, 100, 80, 55, 35, 22, 12, 5, 0, -15, 8),
    ('EBITDA_TO_INTEREST', 'LEVERAGE_COVERAGE', 5, 40, 20, 12, 7, 4, 2.5, 1.5, 1, 0, 9),
    ('DSCR', 'LEVERAGE_COVERAGE', 4, 6, 4, 2.75, 2, 1.5, 1.25, 1, 0.8, 0, 10),
    ('CFO_TO_DEBT', 'LEVERAGE_COVERAGE', 4, 150, 80, 50, 35, 20, 10, 5, 0, -20, 11),
    ('TL_TO_TNW', 'CAPITAL_SOLVENCY', 6, 0, 0.25, 0.6, 1, 1.75, 2.75, 4, 6, 10, 12),
    ('REALISABLE_COVERAGE', 'CAPITAL_SOLVENCY', 2, 3, 2.2, 1.6, 1.2, 0.95, 0.75, 0.55, 0.35, 0.15, 13),
    ('CONTINGENT_TO_TNW', 'CAPITAL_SOLVENCY', 2, -1, -0.5, -0.1, 0.4, 1, 1.6, 2.5, 4, 7, 14),
    ('LIQUIDITY_COVERAGE', 'LIQUIDITY_FUNDING', 4, 4, 3, 2, 1.5, 1.15, 0.85, 0.6, 0.4, 0.2, 15),
