MERGE fin.ScorecardSubfactor AS d
USING (SELECT sc.ScorecardId, m.CreditMetricId AS MetricId, v.Code, v.NameAr, v.NameEn, v.GuideAr, v.SortOrder
       FROM (VALUES
    ('BUSINESS_PROFILE', 'MARKET_POSITION', N'المركز السوقي والحصة', N'Market position and share',
     N'Aa: رائد في سوقه بحصة تفوق 30% وعلامة أو وكالة يصعب منافستها | A: من أكبر ثلاثة في سوقه بحصة 15–30% وقوة تسعير واضحة | Baa: لاعب راسخ بحصة 5–15% يتبع أسعار السوق | Ba: لاعب متوسط أو إقليمي بحصة دون 5% وبلا ميزة تسعير | B: لاعب صغير في سوق مجزأة، يسهل استبداله', 1),
    ('BUSINESS_PROFILE', 'DIVERSIFICATION', N'تنوع المنتجات والأسواق', N'Product and market diversification',
     N'Aa: خطوط منتجات ومناطق كثيرة لا يتجاوز أي منها 20% من الربح | A: عدة خطوط ومناطق، وأكبرها دون 35% | Baa: خطان أو ثلاثة رئيسية في سوق محلي واحد | Ba: منتج أو نشاط رئيسي واحد مع نشاط مساند | B: منتج واحد أو مشروع واحد أو مدينة واحدة', 2),
    ('BUSINESS_PROFILE', 'CONCENTRATION', N'تركّز العملاء والموردين', N'Customer and supplier concentration',
     N'Aa: أكبر عميل دون 5% وأكبر خمسة دون 15%، وموردون بدائل متاحون | A: أكبر عميل دون 10% وأكبر خمسة دون 30% | Baa: أكبر عميل 10–20% أو أكبر خمسة 30–50%، أو مورد رئيسي له بدائل | Ba: أكبر عميل 20–40% أو أكبر خمسة 50–75%، أو وكالة واحدة حرجة | B: عميل واحد فوق 40% أو مورد أو وكالة وحيدة بلا بديل', 3),
    ('BUSINESS_PROFILE', 'SALES_TYPE', N'نوع المبيعات وجودة المدينين', N'Type of sales and debtor quality',
     N'Aa: مبيعات نقدية أو متعاقد عليها لمدينين حكوميين أو مصنفين، وخسائر ائتمان شبه معدومة | A: معظمها لعملاء كبار بعقود، أو نقدية بنسبة عالية، وتحصيل منتظم | Baa: مبيعات آجلة لعملاء تجاريين متنوعين بشروط 60–90 يومًا | Ba: مبيعات آجلة طويلة أو لعملاء صغار، أو حصة ذات علاقة ملحوظة | B: مبيعات آجلة طويلة بلا ضمانات وتحصيل متعثر أو لأطراف ذات علاقة', 4),
    ('BUSINESS_PROFILE', 'DEMAND_STABILITY', N'استقرار الطلب ومخاطر القطاع', N'Demand stability and sector risk',
     N'Aa: طلب أساسي غير دوري وتنظيم يحمي السوق | A: طلب مستقر مع دورية خفيفة | Baa: طلب مرتبط بالنمو الاقتصادي والإنفاق الحكومي بدورية معتدلة | Ba: طلب دوري أو مرتبط بمشاريع وأسعار سلع متقلبة | B: طلب شديد التقلب أو قطاع في تراجع هيكلي', 5),
    ('FINANCIAL_POLICY', 'DISTRIBUTION_POLICY', N'سياسة التوزيعات والمسحوبات', N'Dividend and drawings policy',
     N'Aa: توزيعات مقيدة بسياسة مكتوبة دون 30% من الربح ولا مسحوبات | A: توزيعات دون 50% من الربح ولا تتجاوز التدفق الحر | Baa: توزيعات أو مسحوبات تقارب الربح في السنوات الجيدة | Ba: مسحوبات تتجاوز الربح أحيانًا أو تُمول بالدين | B: مسحوبات منتظمة تفوق الربح، وحسابات جارية مدينة للشركاء', 1),
    ('FINANCIAL_POLICY', 'LEVERAGE_TARGET', N'سياسة الرفع والتمويل', N'Leverage and funding policy',
     N'Aa: سقف رفع معلن ومحترم، وتمويل الأصول الطويلة بتمويل طويل | A: رفع معتدل مستهدف وآجال تمويل متوافقة مع الأصول | Baa: لا سقف معلن، ورفع يرتفع مع النمو ثم ينخفض | Ba: نمو أو استحواذات ممولة بدين قصير الأجل | B: رفع متصاعد بلا خطة، وتمويل أصول طويلة بخطوط قصيرة', 2),
    ('FINANCIAL_POLICY', 'RELATED_PARTY_GOVERNANCE', N'حوكمة تعاملات الأطراف ذات العلاقة', N'Related-party governance',
     N'Aa: تعاملات محدودة بشروط السوق ويعتمدها مجلس أو لجنة مستقلة | A: تعاملات تجارية موثقة بعقود وأسعار السوق | Baa: أرصدة متبادلة مع شركات الشركاء دون إطار مكتوب | Ba: أرصدة مدينة كبيرة على الشركاء أو الشقيقات دون جدول سداد | B: تحويلات متكررة للشركاء أو كفالات لشقيقات متعثرة', 3),
    ('FINANCIAL_POLICY', 'DISCLOSURE_TIMELINESS', N'الإفصاح وتوقيت القوائم', N'Disclosure and timeliness',
     N'Aa: قوائم مدققة من مكتب كبير خلال 90 يومًا، وقوائم ربعية، وإفصاح كامل | A: قوائم مدققة خلال 120 يومًا وإفصاحات المعايير كاملة | Baa: قوائم مدققة خلال ستة أشهر وإفصاح عادي | Ba: تأخر في القوائم أو تحفظ سابق أو إفصاح ناقص عن الأعمار والضمانات | B: قوائم إدارية فقط أو تحفظ جوهري أو تغيير متكرر للمراجع', 4),
    ('FINANCIAL_POLICY', 'BANKING_TRACK_RECORD', N'السجل مع البنوك', N'Banking track record',
     N'Aa: لا تأخر ولا خرق في عشر سنوات، وعلاقات مع عدة بنوك | A: لا تأخر، وخرق فني نادر عولج بسرعة | Baa: تأخر فني محدود أو تنازل واحد عن تعهد | Ba: إعادة جدولة سابقة أو تنازلات متكررة | B: تعثر أو إعادة هيكلة قائمة أو قضايا تنفيذ', 5)
            ) AS v (MetricCode, Code, NameAr, NameEn, GuideAr, SortOrder)
       JOIN fin.Scorecard AS sc ON sc.Code = 'GENERAL_CORPORATE' AND sc.VersionNo = 2 AND sc.Status = 'DRAFT'
       JOIN fin.CreditMetric AS m ON m.Code = v.MetricCode) AS s
   ON d.ScorecardId = s.ScorecardId AND d.MetricId = s.MetricId AND d.Code = s.Code
WHEN NOT MATCHED THEN
    INSERT (ScorecardId, MetricId, Code, NameAr, NameEn, GuideAr, SortOrder) VALUES (s.ScorecardId, s.MetricId, s.Code, s.NameAr, s.NameEn, s.GuideAr, s.SortOrder);
UPDATE fin.Scorecard SET Status = 'APPROVED', EffectiveFrom = '2026-10-19'
WHERE Code = 'GENERAL_CORPORATE' AND VersionNo = 2 AND Status = 'DRAFT';
