     N'المسحوب في سمة يزيد على دين القوائم بأكثر من 15%: تنزيل درجة واحدة، ويُضاف الفرق إلى الدين المعدل',
     N'Bureau outstanding exceeds the statement debt by more than 15%: one notch down, and the difference is added to adjusted debt'),
    ('RESILIENCE', 'NOTCH', -1, NULL, 3, 'ALWAYS', N'ضعف الصمود في الركود',
     N'التقييم في سيناريو ركود السوق يخسر أكثر من {p} درجات: تنزيل درجة واحدة لضعف الصمود',
     N'The stagnant-market assessment loses more than {p} notches: one notch down for weak resilience'),
    ('FX_UNHEDGED', 'NOTCH', -1, NULL, 20, 'ALWAYS', N'مركز عملات غير مغطى',
     N'مركز مكشوف بعملات غير مرتبطة يتجاوز {p}% من صافي الثروة ولا يغطي التحوط نصفه: تنزيل درجة واحدة',
     N'An open position in non-pegged currencies above {p}% of net worth, less than half hedged: one notch down'),
    ('INDUSTRY_CEILING', 'STANDALONE', 0, 'Aaa', NULL, 'WHEN_BINDING', N'سقف النشاط',
     N'سقف نشاط الشركة: لا تتجاوز الدرجة المنفردة سقف القطاع',
     N'The industry ceiling: the standalone grade does not exceed the sector''s ceiling'),
    ('SECTOR_CEILING', 'STANDALONE', 0, 'Baa2', NULL, 'WHEN_BINDING', N'سقف قطاع المقاولات',
     N'قطاع المقاولات: لا تتجاوز الدرجة المنفردة Baa2 (تقلّب الطلب الحكومي وتجربة 2016–2018)',
     N'Contracting sector: standalone grade capped at Baa2 (volatile public demand, the 2016-2018 experience)')
            ) AS v (RuleCode, Stage, Notches, CapGrade, ParamValue, ShowWhen, NameAr, TextAr, TextEn)
       JOIN fin.Scorecard AS sc ON sc.Code = 'CONTRACTING' AND sc.VersionNo = 2 AND sc.Status = 'DRAFT'
       LEFT JOIN fin.RatingGrade AS g ON g.Code = v.CapGrade) AS s
   ON d.ScorecardId = s.ScorecardId AND d.RuleCode = s.RuleCode
WHEN NOT MATCHED THEN
    INSERT (ScorecardId, RuleCode, Stage, Notches, CapGradeId, ParamValue, ShowWhen, IsActive, NameAr, TextAr, TextEn)
    VALUES (s.ScorecardId, s.RuleCode, s.Stage, s.Notches, s.CapGradeId, s.ParamValue, s.ShowWhen, 1, s.NameAr, s.TextAr, s.TextEn);
